tiles.exec:
UPS=ups@localhost
upsc "$UPS" 2>/dev/null | awk -F': ' '
function add(s) { printf "%s%s", (n++ ? "," : ""), s }
{ v[$1] = $2 }
END {
  printf "["
  st = v["ups.status"]
  if (st != "") {
    state = st ~ /LB|RB|OVER|OFF/ ? "bad" : st ~ /OB|DISCHRG|BYPASS|CAL/ ? "warn" : "ok"
    word = st ~ /OB/ ? "on battery" : "on line power"
    add(sprintf("{\"id\":\"ups_status\",\"name\":\"UPS\",\"type\":\"status\",\"value\":\"%s\",\"label\":\"%s\",\"icon\":\"plug\"}", state, word))
  }
  if (v["battery.charge"] ~ /^[0-9.]+$/) add(sprintf("{\"id\":\"ups_charge\",\"name\":\"UPS battery\",\"type\":\"gauge\",\"value\":%s,\"unit\":\"percent\",\"invert\":true,\"warn\":40,\"bad\":15,\"icon\":\"battery\",\"history\":true}", v["battery.charge"]))
  if (v["battery.runtime"] ~ /^[0-9.]+$/) add(sprintf("{\"id\":\"ups_runtime\",\"name\":\"UPS runtime\",\"type\":\"number\",\"value\":%s,\"unit\":\"s\",\"icon\":\"timer\"}", v["battery.runtime"]))
  if (v["ups.load"] ~ /^[0-9.]+$/) add(sprintf("{\"id\":\"ups_load\",\"name\":\"UPS load\",\"type\":\"gauge\",\"value\":%s,\"unit\":\"percent\",\"icon\":\"bolt\"}", v["ups.load"]))
  print "]"
}'
